{
  "schema_version": "spine_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "title": "Welcome to the RNG-Hellscape",
      "goal": "Artie survives his first encounter and establishes his 1 HP / 100% Crit anomaly status in Oakhaven.",
      "chapter_role": "hook",
      "stakes_shift": "From mundane office drone to a high-value system anomaly targeted by a powerful rival.",
      "bridge": {
        "from_prev": "Artie dies in a vending machine accident and enters the character creation void.",
        "to_next": "Artie must find a way to survive his fragility by acquiring gear that compensates for his 1 HP."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 2,
      "title": "The Glass Cannon’s Guide to Not Dying",
      "goal": "Artie acquires the Cloak of the Cowardly Lion and begins exploiting the system's loot mechanics in the crypts.",
      "chapter_role": "setup",
      "stakes_shift": "From desperate survival to tactical exploitation of the system's physics and drop rates.",
      "bridge": {
        "from_prev": "Artie escapes Vane but remains a one-hit-kill target.",
        "to_next": "Artie's rapid farming triggers the attention of the Floor Guardian."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 9
      }
    },
    {
      "chapter_id": 3,
      "title": "Math-Boss vs. The Glitch",
      "goal": "Artie defeats the Bone Golem through a physics exploit and reaches Level 10, becoming a recognized threat.",
      "chapter_role": "pressure",
      "stakes_shift": "From local anomaly to a system-level glitch that threatens the established power hierarchy.",
      "bridge": {
        "from_prev": "Artie summons the Floor Guardian to maximize his XP gains.",
        "to_next": "Vane's fury over the stolen kill forces Artie to flee toward the capital city."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 4,
      "title": "The Capital of Crits",
      "goal": "Artie infiltrates the RNG-worshipping capital and enters the Grand Crit-Off to secure the Shield of Infinite Health.",
      "chapter_role": "investigation",
      "stakes_shift": "From physical survival to a high-stakes social and political gamble against the High Priest's son.",
      "bridge": {
        "from_prev": "Artie arrives at the capital seeking a way to fix his stats.",
        "to_next": "The tournament begins, forcing Artie to fight in a public arena where his glitch is on full display."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 11
      }
    },
    {
      "chapter_id": 5,
      "title": "The Tournament of Tiers",
      "goal": "Artie advances to the finals by weaponizing the system's own glitches against increasingly absurd opponents.",
      "chapter_role": "trial",
      "stakes_shift": "From a simple tournament participant to a target of direct System intervention and rigged mechanics.",
      "bridge": {
        "from_prev": "Artie registers for the tournament and faces his first round of opponents.",
        "to_next": "Vane prepares a System Override scroll to ensure Artie's permanent deletion in the final match."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 12
      }
    },
    {
      "chapter_id": 6,
      "title": "The Final Roll",
      "goal": "Artie defeats Vane by critting the system's reflection math and escapes the Administrator's deletion attempt.",
      "chapter_role": "climax",
      "stakes_shift": "From a character in a game to a reality-warping virus that the System can no longer control.",
      "bridge": {
        "from_prev": "The final match begins with Vane holding all the rigged advantages.",
        "to_next": "The world pixelates and Artie is cast into the wireframe Null-Zone."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 7,
      "title": "Rebooting for the Sequel",
      "goal": "Artie accepts his new status as a 'NaN' entity and joins the Beta-Testers to take down the Administrator.",
      "chapter_role": "aftermath",
      "stakes_shift": "From surviving the system to actively planning its overthrow as a legendary glitch.",
      "bridge": {
        "from_prev": "Artie wakes up in the Null-Zone after the arena's collapse.",
        "to_next": "Artie enters the Glitch-Woods, setting the stage for the next book."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "slow_burn",
        "expected_scene_count": 8
      }
    }
  ]
}

